const CLRS_TXTL = ["tan", "orange", "steelblue", "darkred", "darkgreen", "navy"];
const CLRS_SKIN = ["rgb(48,32,4)", "rgb(235,229,203)", "darkorange"];
const SZE = 50;
const GR_S = ~~(SZE/4);

function setup() {
	createCanvas(windowWidth, windowHeight);
	describe("croud of abstract people filling the canvas over time with various body and textile colors to represent resistance against autocratic regimes which wants to supress diversity");
	background(32);
	noStroke();
	rectMode(CENTER);
}

function draw() {
	drawPeople(~~(random(width)/GR_S)*GR_S, ~~(random(height)/GR_S)*GR_S, random(0.9, 1.1)*SZE);
}

function drawPeople(x, y, s) {
	s = map(y, 0, height, s*0.5, s*2)
	fill(lerpClrArr(CLRS_TXTL, random()));
	rect(x, y, s/5, s, s/20);
	fill(lerpClrArr(CLRS_TXTL, random()));
	rect(x, y-s/10, s/2, s/2, s/10);
	fill(lerpClrArr(CLRS_SKIN, random()));
	circle(x, y-s/2, s/3);
}

function lerpClrArr(clrArr, f) {
	f *= clrArr.length;
	const idx1 =  ~~f;
	const idx2 = (idx1 + 1) % clrArr.length;
	if (typeof clrArr[idx1] == "string") clrArr[idx1] = color(clrArr[idx1]);
	if (typeof clrArr[idx2] == "string") clrArr[idx2] = color(clrArr[idx2]);
	return lerpColor(clrArr[idx1], clrArr[idx2], fract(f))
}
